// editar_evento: precio, precioEstado y precioDetalle se traducen a precioInfo (una sola vía de validación). precio:null = desconocido.
export function precioACambios(c){
 const t=['precio','precioEstado','precioDetalle'].some(k=>k in c);if(!t)return c;
 if('precioInfo' in c)fail('invalid_changes',{ayuda:'No combines precioInfo con precio/precioEstado/precioDetalle.'});
 const {precio,precioEstado,precioDetalle,...resto}=c;
 const estado=precioEstado??(precio===null?'desconocido':undefined);
 if(estado===undefined){if(precioDetalle!==undefined)fail('invalid_changes',{ayuda:'precioDetalle exige precioEstado.'});return c;}
 if(estado==='desconocido'&&precio!=null)fail('invalid_changes',{ayuda:'Con precioEstado "desconocido" el precio debe ser null o ir ausente.'});
 const info={estado};
 if(precio!=null)info.cantidad=precio;
 if(typeof precioDetalle==='string')info.textoOriginal=precioDetalle;
 else if(precioDetalle&&typeof precioDetalle==='object'){for(const [k,v] of Object.entries(precioDetalle))if(v!=null)info[k]=v;}
 return {...resto,precioInfo:info};
}
